"""Expand a ComfyUI *UI* workflow (subgraphs included) into an API prompt.

``POST /prompt`` only accepts the *API* shape: a flat map of
``node_id -> {class_type, inputs}`` where each input is a literal or a
``[node_id, slot]`` link. The frontend builds that map in the browser through
``app.graphToPrompt()``, including the expansion of every subgraph instance.
The phone page has no graph, so the expansion happens here instead.

Why the file is parsed instead of recomputing widget order
----------------------------------------------------------
Deriving ``widgets_values`` order from ``INPUT_TYPES`` looks tempting but is
wrong in practice: on the machine this was written against, 56 of 287 nodes in
the saved workflows disagree with their definitions (custom nodes with dynamic
widgets, ``control_after_generate`` extras, virtual nodes). The serialized
``inputs[].widget.name`` markers are exact, so values are read by name from
the file itself. Their one irregularity is that a seed widget is followed by
an extra ``control_after_generate`` string, which :func:`_widget_map` skips.

How a promoted input is resolved
--------------------------------
* A subgraph instance is a node whose ``type`` is a ``definitions.subgraphs``
  uuid. Its ``widgets_values`` hold the promoted input values, keyed by name
  through its own ``inputs[].widget.name`` markers.
* Inside the definition, links whose ``origin_id`` equals the definition's
  ``inputNode.id`` start at the input node, so ``origin_slot`` is the
  promoted-input index and the link's target is the node input receiving it.
  The instance's value for that index overrides whatever the inner node
  serialized, because promotion is an override.
* That target is exactly what a new value has to overwrite, and is reported
  as a *parameter target*: ``(exec_id, input_name)``.

Execution ids follow the frontend convention of colon-separated node ids,
e.g. ``64:27`` for node 27 inside subgraph instance 64.
"""

from __future__ import annotations

from typing import Any

#: Fallback sentinel ids for a subgraph's boundary nodes.
DEFAULT_INPUT_NODE_ID = -10
DEFAULT_OUTPUT_NODE_ID = -20

#: Node modes that mean "do not execute".
MODE_NEVER = 2
MODE_BYPASS = 4

#: Slot types the frontend renders as a value widget.
WIDGET_KINDS = {"INT", "FLOAT", "STRING", "BOOLEAN", "COMBO"}

#: Widget names the frontend follows with an extra control value.
SEED_WIDGET_NAMES = {"seed", "noise_seed"}

#: Values the extra seed control widget can take.
SEED_CONTROL_VALUES = {"fixed", "increment", "decrement", "randomize"}


class GraphExpansionError(ValueError):
    """Raised when a workflow cannot be expanded into a prompt."""


def _link_index(graph: dict[str, Any]) -> dict[int, dict[str, Any]]:
    """Index a graph's links by id, normalising legacy array links."""
    index: dict[int, dict[str, Any]] = {}
    for entry in graph.get("links") or []:
        if isinstance(entry, dict):
            if entry.get("id") is None:
                continue
            index[int(entry["id"])] = entry
        elif isinstance(entry, list) and len(entry) >= 5:
            index[int(entry[0])] = {
                "id": entry[0],
                "origin_id": entry[1],
                "origin_slot": entry[2],
                "target_id": entry[3],
                "target_slot": entry[4],
                "type": entry[5] if len(entry) > 5 else None,
            }
    return index


def _subgraph_definitions(workflow: dict[str, Any]) -> dict[str, dict[str, Any]]:
    definitions = workflow.get("definitions") or {}
    return {
        str(subgraph["id"]): subgraph
        for subgraph in definitions.get("subgraphs") or []
        if subgraph.get("id")
    }


def _is_active(node: dict[str, Any]) -> bool:
    return node.get("mode", 0) not in (MODE_NEVER, MODE_BYPASS)


def _widget_names(node: dict[str, Any]) -> list[str]:
    """Widget names in serialization order, from the node's own input slots."""
    return [
        (slot.get("widget") or {}).get("name")
        for slot in node.get("inputs") or []
        if slot.get("widget")
    ]


def _widget_map(node: dict[str, Any]) -> dict[str, Any]:
    """``{widget_name: value}``, skipping the seed control value.

    Widgets that the node does not expose as a named input still need to reach
    the prompt, yet they have no name to key them by. They are kept under
    ``_positional`` in serialization order so the caller can fall back to them
    instead of inventing names.
    """
    raw = node.get("widgets_values")
    names = _widget_names(node)
    if isinstance(raw, dict):
        mapped = {name: raw.get(name) for name in names if name}
        return mapped
    if not isinstance(raw, list):
        return {}

    mapped: dict[str, Any] = {}
    cursor = 0
    for name in names:
        if not name or cursor >= len(raw):
            break
        mapped[name] = raw[cursor]
        cursor += 1
        control = raw[cursor] if cursor < len(raw) else None
        if name in SEED_WIDGET_NAMES and control in SEED_CONTROL_VALUES:
            cursor += 1
    return mapped


def widget_slots(node: dict[str, Any]) -> list[tuple[str, Any, Any, Any]]:
    """``[(控件名, 位置, 值, 种子控制值)]``，顺序与前端控件一致。

    与 :func:`_widget_map` 用同一套游标规则（种子控件后面多占一位），
    所以按位置写回去的值和读出来的值落在同一格。种子控制值只有
    ``randomize`` 这类后缀才带，其余控件为 ``None``。dict 形式的
    ``widgets_values`` 没有位置概念，位置填 ``None``。
    """
    raw = node.get("widgets_values")
    names = _widget_names(node)
    if isinstance(raw, dict):
        return [(name, None, raw.get(name), None) for name in names if name]
    if not isinstance(raw, list):
        return []

    slots: list[tuple[str, Any, Any, Any]] = []
    cursor = 0
    for name in names:
        if not name or cursor >= len(raw):
            break
        control = None
        if (
            name in SEED_WIDGET_NAMES
            and cursor + 1 < len(raw)
            and raw[cursor + 1] in SEED_CONTROL_VALUES
        ):
            control = raw[cursor + 1]
        slots.append((name, cursor, raw[cursor], control))
        cursor += 2 if control is not None else 1
    return slots


def set_widget_value(node: dict[str, Any], name: str, value: Any) -> bool:
    """把值写回控件；找不到同名控件返回 False。"""
    raw = node.get("widgets_values")
    for widget_name, index, _current, _control in widget_slots(node):
        if widget_name != name:
            continue
        if isinstance(raw, dict):
            raw[name] = value
        elif index is not None:
            raw[index] = value
        return True
    return False


def prompt_nodes(workflow: dict[str, Any]) -> list[tuple[str, dict[str, Any]]]:
    """``[(执行 id, 节点)]``，执行 id 与前端提交的 prompt 键一致。

    子图实例展开进各自定义，执行 id 用冒号连接（``64:27``）；静音/绕过
    的节点不进 prompt，这里同样跳过。只读遍历，不做取值合并——需要
    合并后的值请用 :func:`expand_workflow`。
    """
    definitions = _subgraph_definitions(workflow)
    found: list[tuple[str, dict[str, Any]]] = []

    def walk(container: dict[str, Any], prefix: str) -> None:
        for node in container.get("nodes") or []:
            if not isinstance(node, dict) or node.get("id") is None:
                continue
            if not _is_active(node):
                continue
            exec_id = f"{prefix}{node.get('id')}"
            inner = definitions.get(str(node.get("type")))
            if inner is not None:
                walk(inner, f"{exec_id}:")
            else:
                found.append((exec_id, node))

    walk(workflow, "")
    return found


def _raw_widgets(node: dict[str, Any]) -> Any:
    return node.get("widgets_values")


def _node_index(graph: dict[str, Any]) -> dict[Any, dict[str, Any]]:
    return {node.get("id"): node for node in graph.get("nodes") or []}


def _input_node_id(definition: dict[str, Any] | None) -> Any:
    if not definition:
        return DEFAULT_INPUT_NODE_ID
    return (definition.get("inputNode") or {}).get("id", DEFAULT_INPUT_NODE_ID)


def _output_node_id(definition: dict[str, Any] | None) -> Any:
    if not definition:
        return DEFAULT_OUTPUT_NODE_ID
    return (definition.get("outputNode") or {}).get("id", DEFAULT_OUTPUT_NODE_ID)


def _slot_name(node: dict[str, Any], slot_index: int) -> str | None:
    slots = node.get("inputs") or []
    if 0 <= slot_index < len(slots):
        return slots[slot_index].get("name")
    return None


class _Expander:
    def __init__(self, workflow: dict[str, Any]) -> None:
        self.workflow = workflow
        self.definitions = _subgraph_definitions(workflow)
        self.prompt: dict[str, dict[str, Any]] = {}
        self.parameters: list[dict[str, Any]] = []

    def run(self) -> dict[str, Any]:
        self._walk(self.workflow, None, "", {})
        return {"prompt": self.prompt, "parameters": self.parameters}

    # -- traversal -------------------------------------------------------
    def _walk(
        self,
        graph: dict[str, Any],
        definition: dict[str, Any] | None,
        prefix: str,
        promoted: dict[int, Any],
        inherited: dict[str, Any] | None = None,
    ) -> None:
        links = _link_index(graph)
        nodes = _node_index(graph)
        input_id = _input_node_id(definition)
        boundary = {input_id, _output_node_id(definition)}
        # Reroute resolution needs this graph's links while walking its nodes.
        self._reroute_links = {id(node): links for node in nodes.values()}

        for node in graph.get("nodes") or []:
            node_id = node.get("id")
            if node_id in boundary and str(node.get("type")) not in self.definitions:
                continue
            if not _is_active(node):
                continue
            if str(node.get("type")) == "Reroute":
                # Virtual pass-through: the frontend drops these from the prompt.
                continue
            exec_id = f"{prefix}{node_id}"
            if str(node.get("type")) in self.definitions:
                # Values promoted by THIS graph reach the instance through its
                # input slots; they take precedence over what it serialized.
                overrides = self._instance_overrides(node, links, promoted, input_id)
                self._walk_instance(node, exec_id, overrides)
                continue
            self.prompt[exec_id] = self._build_node(
                node, nodes, links, prefix, promoted, input_id
            )

    def _instance_overrides(
        self,
        instance: dict[str, Any],
        links: dict[int, dict[str, Any]],
        promoted: dict[int, Any],
        input_node_id: Any,
    ) -> dict[str, Any]:
        """Values this graph's promotions push into an instance's own slots."""
        overrides: dict[str, Any] = {}
        for slot in instance.get("inputs") or []:
            name = slot.get("name")
            link_id = slot.get("link")
            if not name or link_id is None:
                continue
            link = links.get(int(link_id))
            if link is None or link.get("origin_id") != input_node_id:
                continue
            overrides[name] = promoted.get(int(link.get("origin_slot") or 0))
        return overrides

    def _walk_instance(
        self,
        instance: dict[str, Any],
        exec_id: str,
        overrides: dict[str, Any] | None = None,
    ) -> None:
        """Expand one subgraph instance and describe its promoted inputs."""
        definition = self.definitions[str(instance.get("type"))]
        widgets = _widget_map(instance)
        widgets.update(overrides or {})
        inner_links = _link_index(definition)
        inner_nodes = _node_index(definition)
        input_id = _input_node_id(definition)

        promoted_values: dict[int, Any] = {}
        for index, entry in enumerate(definition.get("inputs") or []):
            name = str(entry.get("name") or "")
            if not name:
                continue
            slot_type = str(entry.get("type") or "")
            targets = self._promoted_targets(index, inner_links, inner_nodes, input_id)
            value = widgets.get(name)
            promoted_values[index] = value
            self.parameters.append(
                {
                    "key": f"{exec_id}:{name}",
                    "name": name,
                    "label": entry.get("label") or entry.get("localized_name") or name,
                    "type": slot_type,
                    "combo": slot_type in ("COMBO", "combo"),
                    "value": value,
                    "targets": [
                        [f"{exec_id}:{node_id}", input_name]
                        for node_id, input_name in targets
                    ],
                }
            )

        self._walk(definition, definition, f"{exec_id}:", promoted_values)

    def _promoted_targets(
        self,
        index: int,
        inner_links: dict[int, dict[str, Any]],
        inner_nodes: dict[Any, dict[str, Any]],
        input_node_id: Any,
    ) -> list[tuple[str, str]]:
        """``(inner_node_id, input_name)`` pairs fed by promoted input *index*."""
        found: list[tuple[str, str]] = []
        for link in inner_links.values():
            if link.get("origin_id") != input_node_id:
                continue
            if int(link.get("origin_slot") or 0) != index:
                continue
            target_node = inner_nodes.get(link.get("target_id"))
            if target_node is None:
                continue
            name = _slot_name(target_node, int(link.get("target_slot") or 0))
            if name:
                found.append((str(target_node.get("id")), name))
        return found

    # -- node building ---------------------------------------------------
    def _build_node(
        self,
        node: dict[str, Any],
        nodes: dict[Any, dict[str, Any]],
        links: dict[int, dict[str, Any]],
        prefix: str,
        promoted: dict[int, Any],
        input_node_id: Any,
    ) -> dict[str, Any]:
        widgets = _widget_map(node)
        inputs: dict[str, Any] = {}

        for slot in node.get("inputs") or []:
            name = slot.get("name")
            if not name:
                continue
            link_id = slot.get("link")
            if link_id is None:
                if name in widgets:
                    inputs[name] = widgets[name]
                continue
            link = links.get(int(link_id))
            if link is None:
                continue
            origin = link.get("origin_id")
            slot_index = int(link.get("origin_slot") or 0)

            if origin == input_node_id:
                # Promotion overrides whatever the inner node serialized.
                inputs[name] = promoted.get(slot_index)
                continue
            resolved = self._resolve_link(nodes, origin, slot_index, prefix)
            if resolved is not None:
                inputs[name] = list(resolved)

        for name, value in widgets.items():
            inputs.setdefault(name, value)

        return {"class_type": node.get("type"), "inputs": inputs}

    def _resolve_link(
        self,
        nodes: dict[Any, dict[str, Any]],
        origin: Any,
        slot_index: int,
        prefix: str,
    ) -> tuple[str, int] | None:
        """Resolve a link origin, passing through Reroute nodes.

        Reroute carries no data of its own: the frontend splices it out so that
        consumers point straight at the real producer.
        """
        seen: set[Any] = set()
        current = origin
        current_slot = slot_index
        while current is not None:
            if current in seen:
                return None
            seen.add(current)
            node = nodes.get(current)
            if node is None:
                return None
            if str(node.get("type")) in self.definitions:
                return self._instance_output(node, current_slot, prefix)
            if str(node.get("type")) == "Reroute":
                upstream = node.get("inputs") or []
                if not upstream or upstream[0].get("link") is None:
                    return None
                parent_links = self._reroute_links.get(id(node)) or {}
                link = parent_links.get(int(upstream[0]["link"]))
                if link is None:
                    return None
                current = link.get("origin_id")
                current_slot = int(link.get("origin_slot") or 0)
                continue
            return (f"{prefix}{current}", current_slot)
        return None

    def _instance_output(
        self, instance: dict[str, Any], slot_index: int, prefix: str
    ) -> tuple[str, int] | None:
        """Resolve a link leaving a subgraph instance to a concrete inner node."""
        definition = self.definitions[str(instance.get("type"))]
        inner_links = _link_index(definition)
        inner_nodes = _node_index(definition)
        output_id = _output_node_id(definition)
        instance_exec = f"{prefix}{instance.get('id')}"

        outputs = definition.get("outputs") or []
        link_ids: list[Any] = []
        if slot_index < len(outputs):
            link_ids = list(outputs[slot_index].get("linkIds") or [])

        candidates = [inner_links.get(int(lid)) for lid in link_ids]
        candidates += [
            link
            for link in inner_links.values()
            if link.get("target_id") == output_id
        ]

        for inner_link in candidates:
            if inner_link is None:
                continue
            origin = inner_link.get("origin_id")
            origin_slot = int(inner_link.get("origin_slot") or 0)
            inner_node = inner_nodes.get(origin)
            if inner_node is None:
                continue
            if str(inner_node.get("type")) in self.definitions:
                nested = self._instance_output(
                    inner_node, origin_slot, f"{instance_exec}:"
                )
                if nested is not None:
                    return nested
                continue
            return (f"{instance_exec}:{origin}", origin_slot)
        return None


def expand_workflow(workflow: dict[str, Any]) -> dict[str, Any]:
    """Expand *workflow* into ``{"prompt": ..., "parameters": ...}``."""
    return _Expander(workflow).run()


__all__ = ["expand_workflow", "GraphExpansionError"]
